// UTMs arrive as a query string, an object, or not at all. Normalise all three,
// and keep the referrer as a fallback so direct traffic is not simply "unknown".
function fromQuery(qs) {
  const out = {};
  String(qs || '').replace(/^\?/, '').split('&').forEach((pair) => {
    if (!pair) return;
    const [k, v] = pair.split('=');
    out[decodeURIComponent(k)] = decodeURIComponent(v || '');
  });
  return out;
}
return $input.all().map((item) => {
  const src = item.json;
  const q = typeof src.query_string === 'string' ? fromQuery(src.query_string) : (src.utm || src.query || {});
  const referrer = src.referrer || src.referer || '';
  let channel = q.utm_medium || '';
  if (!channel && referrer) {
    if (/instagram|facebook|tiktok|linkedin|x\.com|twitter/i.test(referrer)) channel = 'social';
    else if (/google|bing|duckduckgo/i.test(referrer)) channel = 'organic_search';
    else channel = 'referral';
  }
  return { json: Object.assign({}, src, { touch: {
    email: (src.email || (src.lead && src.lead.email) || '').toLowerCase(),
    utm_source: q.utm_source || '',
    utm_medium: q.utm_medium || '',
    utm_campaign: q.utm_campaign || '',
    utm_content: q.utm_content || '',
    utm_term: q.utm_term || '',
    referrer,
    channel: channel || 'direct',
    landing_page: src.landing_page || src.page || '',
    occurred_at: src.occurred_at || new Date().toISOString()
  } }) };
});

// First touch gets the credit for creating demand, last touch for capturing it.
// Both are stored - arguing about which one is "right" is not this pack's job.
const touches = $input.all().map((i) => i.json).filter((t) => t.occurred_at);
touches.sort((a, b) => new Date(a.occurred_at) - new Date(b.occurred_at));
const first = touches[0] || null;
const last = touches[touches.length - 1] || null;
const email = $('Parse UTM').first().json.touch.email;
const label = (t) => (t ? [t.utm_source || t.channel, t.utm_campaign].filter(Boolean).join(' / ') : 'unknown');
return [{ json: {
  lead: { email },
  attribution: {
    first_touch: label(first),
    first_touch_at: first ? first.occurred_at : null,
    last_touch: label(last),
    last_touch_at: last ? last.occurred_at : null,
    touch_count: touches.length,
    path: touches.map((t) => t.utm_source || t.channel).join(' > ')
  }
} }];
